use std::fs

fn best(pr: Vec<int>) -> int {
    let mut b = 0
    let mut i = 1
    while i < pr.len() as int {
        if pr[i] > pr[b] {
            b = i
        }
        i += 1
    }
    b
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut names: Vec<string> = []
    let mut pr: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        let n: int = parts.len() as int
        if n == 0 {
            println("error")
        } else if parts[0] == "add" && n == 3 {
            match parts[2].parse::<int>() {
                Ok(v) => {
                    names.push(parts[1])
                    pr.push(v)
                }
                Err(_) => println("error")
            }
        } else if parts[0] == "pop" && n == 1 {
            if pr.len() == 0 {
                println("empty")
            } else {
                let b = best(pr)
                println(names[b])
                names.remove(b)
                pr.remove(b)
            }
        } else if parts[0] == "peek" && n == 1 {
            if pr.len() == 0 {
                println("empty")
            } else {
                println(names[best(pr)])
            }
        } else if parts[0] == "size" && n == 1 {
            println("${pr.len()}")
        } else {
            println("error")
        }
    }
    println("left:")
    while pr.len() > 0 {
        let b = best(pr)
        println("${names[b]} ${pr[b]}")
        names.remove(b)
        pr.remove(b)
    }
}

